    function closeModal() { document.getElementById('screen-modal').style.display = 'none'; }
    function sendMapCommand() { const command = `/send 文本34 | /trigger`; if (typeof triggerSlash === 'function') triggerSlash(command); }
    function triggerBattle(name) { event.stopPropagation(); const command = `/send 文本35${name}文本36 | /trigger`; if (typeof triggerSlash === 'function') triggerSlash(command); }

    (function initParsers() {

        const rawEquip = document.getElementById('raw-equip-data');
        const equipContainer = document.getElementById('equip-list-container');
        if (rawEquip && equipContainer) {
            let parts = rawEquip.innerText.trim().split('|');
            while(parts.length < 6) parts.push('文本37');
            const slots = ['文本38', '文本39', '文本40'];
            equipContainer.innerHTML = '';
            for(let i=0; i<3; i++) {
                let name = parts[i*2] || '文本41';
                let stat = parts[i*2+1] || '文本41';
                if(name.includes('#')) name = name.split('#')[0]; 
                const div = document.createElement('div');
                div.className = 'equip-item';
                div.onclick = function() { showModal(name, '文本42: ' + stat); };
                div.innerHTML = `<div class="equip-slot">${slots[i]}</div><div class="equip-name">${name}</div>`;
                equipContainer.appendChild(div);
            }
        }

        const rawInv = document.getElementById('raw-inventory-data');
        const invContainer = document.getElementById('inventory-list-container');
        if (rawInv && invContainer) {
            const str = rawInv.innerText.trim();
            if(!str || str.includes('文本41#0')) {
                invContainer.innerHTML = '<div style="text-align:center;padding:10px;color:#888;">文本43</div>';
            } else {
                str.split('&').forEach(itemStr => {
                    const parts = itemStr.split('#');
                    if(parts.length >= 2) {
                        const div = document.createElement('div');
                        div.className = 'inventory-item';
                        div.innerHTML = `<span class="inv-name">${parts[0]}</span><span class="inv-count">x${parts[1]}</span>`;
                        invContainer.appendChild(div);
                    }
                });
            }
        }


        const rawPpl = document.getElementById('raw-people-data');
        const pplContainer = document.getElementById('nearby-list-container');
        if (rawPpl && pplContainer) {
            const str = rawPpl.innerText.trim();
            if(!str || str.includes('文本41#文本41')) {
                pplContainer.innerHTML = '<div style="text-align:center;padding:10px;color:#888;">文本44</div>';
            } else {
                pplContainer.innerHTML = ''; 
                str.split('&').forEach(pStr => {




                    const firstHash = pStr.indexOf('#');
                    const secondHash = pStr.indexOf('#', firstHash + 1);

                    if (firstHash !== -1 && secondHash !== -1) {
                        const role = pStr.substring(0, firstHash).trim();
                        const name = pStr.substring(firstHash + 1, secondHash).trim();
                        let stats = pStr.substring(secondHash + 1).trim();


                        const displayStats = stats.replace(/[\[\]]/g, '');

                        const div = document.createElement('div');
                        div.className = 'nearby-item';
                        div.innerHTML = `
                            <div class="nearby-info" onclick="showModal('${role} ${name}', '${displayStats}')">
                                <span class="nearby-role">${role}</span>
                                <span class="nearby-name">${name}</span>
                            </div>
                            <div class="battle-btn" title="文本45" onclick="triggerBattle('${name}')">⚔️</div>
                        `;
                        pplContainer.appendChild(div);
                    }
                });
            }
        }
    })();
</script>

