const GameLogic = {
    state: { h:0, m:0, week:1, moon:"", stats:{}, inv:"", destroyed: [] },
    init() {
        let tStr = document.getElementById('map-time').value.trim();

        let timeMatch = tStr.match(/(\d{1,2})[:：](\d{2})/);
        this.state.h = timeMatch ? parseInt(timeMatch[1]) : 0;
        this.state.m = timeMatch ? parseInt(timeMatch[2]) : 0;

        let wStr = document.getElementById('map-weekday').value.trim();
        const wMap = {"文本256":1,"文本257":2,"文本173":3,"文本258":4,"文本259":5,"文本97":6,"文本260":7};
        this.state.week = wMap[wStr] || 1;
        this.state.moon = document.getElementById('map-moon').value.trim();
        this.state.inv = document.getElementById('map-inv').value.trim();
        const sStr = document.getElementById('map-stats').value.trim();
        const sArr = sStr.split(',').map(Number);
        this.state.stats = { STR:sArr[0], AGI:sArr[1], CON:sArr[2], WIS:sArr[3], EMP:sArr[4], WIL:sArr[5], LDR:sArr[6], LUCK:sArr[7] };
        const dStr = document.getElementById('map-destroyed').value.trim();
        this.state.destroyed = dStr.includes("文本41") ? [] : dStr.split('&');
    },
    isTime(range) {
        if(!range) return true;
        let [s, e] = range.split('-');
        let [sh, sm] = s.split(':').map(Number);
        let [eh, em] = e.split(':').map(Number);
        let now = this.state.h * 60 + this.state.m;
        let start = sh * 60 + sm;
        let end = eh * 60 + em;
        if(end < start) return now >= start || now <= end;
        return now >= start && now <= end;
    },
    check(loc, parentStatus = {}) {
        if(parentStatus.locked) return { locked: true, msg: "文本261" };
        let status = { open: true };
        if (this.state.destroyed.includes(loc.name) || parentStatus.destroyed) return { destroyed: true, msg: "文本262" };

        if(loc.req) {
            const r = loc.req;
            if(r.attr && this.state.stats[r.attr] < r.val) return { locked: true, msg: `${r.attr}${r.val}` };
            if(r.item && !this.state.inv.includes(r.item)) return { locked: true, msg: `文本263${r.item}` };
            if(r.moon && this.state.moon !== r.moon) return { locked: true, msg: `文本263${r.moon}` };
            if(r.custom) {
                let exp = r.custom
                    .replace(/STR|AGI|CON|WIS|EMP|WIL|LDR|LUCK/g, m=>this.state.stats[m])
                    .replace(/HAS_([^\s&|()]+)/g, (m,i)=>this.state.inv.includes(i))
                    .replace(/time>=(\d+):(\d+)/g, (m,h,min)=>(this.state.h*60+this.state.m)>=(h*60+parseInt(min)))
                    .replace(/day_time/g, (this.state.h>=6&&this.state.h<18))
                    .replace(/day==(\d+)/g, "true")
                    .replace(/week==(\d+)/g, (m,d)=>this.state.week==d);
                try { if(!(new Function(`return ${exp}`)())) return { locked: true, msg: r.desc||"文本264" }; }
                catch(e) { return { locked: true, msg: "文本37" }; }
            }
        }

        if(parentStatus.closed) return { closed: true, msg: "文本265" };
        if(loc.openWeek && !loc.openWeek.includes(this.state.week)) return { closed: true, msg: "文本266" };
        if(loc.openTime && !this.isTime(loc.openTime)) return { closed: true, msg: `文本49:${loc.openTime}` };

        return status;
    }
};

function render() {
    GameLogic.init();
    const nav = document.getElementById('region-nav');
    nav.innerHTML = '';
    WorldMap.forEach((r, i) => {
        let tab = document.createElement('div');
        tab.className = `region-tab ${i==0?'active':''}`;
        tab.innerText = r.region;
        tab.onclick = function(){
            document.querySelectorAll('.region-tab').forEach(e=>e.classList.remove('active'));
            this.classList.add('active');
            loadRegion(i);
        }
        nav.appendChild(tab);
    });
    loadRegion(0);
}

function loadRegion(idx) {
    const list = document.getElementById('location-list');
    list.innerHTML = '';
    WorldMap[idx].groups.forEach(group => {
        let groupStatus = GameLogic.check(group);
        if(groupStatus.locked) {
            let div = document.createElement('div');
            div.className = '文本267';
            div.innerHTML = `<div class="loc-name">🔒 ??? <span class="status-badge bg-locked">文本268</span></div><div class="loc-info">${groupStatus.msg}</div>`;
            list.appendChild(div);
            return;
        }
        let title = document.createElement('div');
        title.className = 'loc-group-title';
        title.innerText = group.name;
        list.appendChild(title);
        if(group.locs) group.locs.forEach(loc => renderLoc(loc, list, groupStatus));
    });
}

function renderLoc(loc, container, parentStatus) {
    let status = GameLogic.check(loc, parentStatus);
    let div = document.createElement('div');
    div.className = 'loc-item';

    if(status.locked) {
        div.classList.add('locked');
        div.innerHTML = `<div class="loc-name">🔒 ??? <span class="status-badge bg-locked">文本52</span></div><div class="loc-info">${status.msg}</div>`;
        container.appendChild(div);
        return;
    }
    if(status.destroyed) {
        div.classList.add('destroyed');
        div.innerHTML = `<div class="loc-name">☠ ${loc.name} <span class="status-badge bg-destroyed">文本262</span></div><div class="loc-info">文本269</div>`;
        container.appendChild(div);
        return;
    }
    if(loc.subs && loc.subs.length > 0) {
        div.classList.add('container-node');
        let html = `<div class="loc-name">${loc.name}</div>`;
        if(status.closed) html += `<div class="loc-info">(文本265)</div>`;
        div.innerHTML = html;
        let wrapper = document.createElement('div');
        wrapper.className = 'loc-content-wrapper';
        container.appendChild(div);
        container.appendChild(wrapper);
        loc.subs.forEach(sub => renderLoc(sub, wrapper, status));
        return;
    }
    if(status.closed) {
        div.classList.add('closed');
        div.innerHTML = `<div class="loc-name">${loc.name} <span class="status-badge bg-closed">文本50</span></div><div class="loc-info">${status.msg}</div>`;
    } else {
        div.classList.add('clickable');
        div.onclick = () => go(loc.name);
        div.innerHTML = `<div class="loc-name">${loc.name} <span class="status-badge bg-open">文本270</span></div>`;
    }
    container.appendChild(div);
}

function go(name) { if(typeof triggerSlash === 'function') triggerSlash(`/send 文本270${name} | /trigger`); }
function closeMap() { if(typeof triggerSlash === 'function') triggerSlash(`/echo 文本271`); }
setTimeout(render, 100);
</script>
