                    <div class="progress-bar ${isSuccess ? '' : 'progress-bar-fail'}" style="width: ${progressPercent}%;"></div>
                    <div class="target-marker" style="left: calc(${targetPercent}% - 1px);"></div>
                    <div class="progress-text">${yourValue} / ${targetValue}</div>
                </div>
                <div class="check-result ${isSuccess ? 'result-success' : 'result-failure'}">${result}</div>
            `;
            container.appendChild(itemDiv);
        });
    })();
</script>

</body>
</html>
