    const rawData = JSON.parse(document.getElementById('battle-raw-data').value);
    const rounds = rawData.rounds;
    const gridEl = document.getElementById('minimized-grid');
    const displayEl = document.getElementById('active-display');
    const resultPanel = document.getElementById('result-panel');
    const showResultBtn = document.getElementById('show-result-btn');

    const btnElements = [];
    rounds.forEach((round, index) => {
        const btn = document.createElement('div');
        btn.className = 'mini-btn';
        btn.innerText = round.attr;
        btn.onclick = () => { if(btn.classList.contains('completed')) showRoundCard(index, false); };
        gridEl.appendChild(btn);
        btnElements.push(btn);
    });

    let currentRoundIndex = 0;
    const ANIMATION_DELAY = 2800; 

    function startSequence() {
        btnElements.forEach((btn, i) => setTimeout(() => btn.classList.add('visible'), i * 100));
        setTimeout(playNextRound, 1000);
    }

    function playNextRound() {
        if(currentRoundIndex >= rounds.length) { setTimeout(showResult, 1000); return; }
        showRoundCard(currentRoundIndex, true);
    }

    function showRoundCard(index, autoNext) {
        const round = rounds[index];
        const v1 = parseInt(round.v1);
        const v2 = parseInt(round.v2);
        const total = v1 + v2 || 1;
        const p1Pct = (v1 / total) * 100;
        const p2Pct = (v2 / total) * 100;

        const html = `
            <div class="compare-card">
                <div class="card-title">ROUND ${index+1}: ${round.attr}</div>
                <div class="card-bar-wrapper">
                    <div class="val-text" style="color:#9f9;">${v1}</div>
                    <div class="bar-track">
                        <div class="bar-segment bar-p1"></div>
                        <div class="bar-segment bar-p2"></div>
                    </div>
                    <div class="val-text" style="color:#f88;">${v2}</div>
                </div>
                <div class="card-comment">${round.cmt}</div>
            </div>`;
        displayEl.innerHTML = html;

        setTimeout(() => {
            const card = displayEl.querySelector('.compare-card');
            if(card) {
                card.querySelector('.bar-p1').style.width = p1Pct + '%';
                card.querySelector('.bar-p2').style.width = p2Pct + '%';
            }
        }, 50);

        if(autoNext) {
            btnElements[index].style.borderColor = '#fff';
            setTimeout(() => {
                btnElements[index].classList.add('completed');
                btnElements[index].style.borderColor = '';
                currentRoundIndex++;
                playNextRound();
            }, ANIMATION_DELAY);
        }
    }

    function showResult() {
        displayEl.innerHTML = '';
        resultPanel.classList.add('show');
        showResultBtn.style.display = 'none';
    }

    window.closeResultPanel = function() {
        resultPanel.classList.remove('show');
        showResultBtn.style.display = 'block';
    }

    window.finishBattle = function(resultStr) {
        let msg = (resultStr.includes("文本284") || resultStr.includes("文本285")) ? "文本286" : "文本287";
        if (rawData.result.includes("文本278") || rawData.result.includes("文本288")) msg = "文本287";
        if (rawData.result.includes("文本284")) msg = "文本286";

        const command = `/send ${msg} | /trigger`;
        if (typeof triggerSlash === 'function') {
            triggerSlash(command);
        } else {
            console.log("CMD:", command);
        }
    };
    setTimeout(startSequence, 500);
</script>

