    const vampireData = {
        "文本313": { desc: "文本369", bond: null },
        "文本315": { desc: "文本370", bond: "文本371", needPartner: true },
        "文本319": { desc: "文本372", bond: "文本373", needSire: true },
        "文本321": { desc: "文本374", bond: "文本375", needSire: false, isHalfBlood: true },
        "文本323": { desc: "文本376", bond: "文本377", needSire: true, isThrall: true }
    };

    const werewolfData = {
        "文本339": { desc: "文本378", bond: "文本379", needSire: false },
        "文本341": { desc: "文本380", bond: null },
        "文本343": { desc: "文本381", bond: "文本382", needPartner: true },
        "文本345": { desc: "文本383", bond: "文本384", needSire: true },
        "文本347": { desc: "文本385", bond: "文本375", needSire: false, isHalfBlood: true },
        "文本349": { desc: "文本386", bond: "文本387", needSire: true, isCursed: true }
    };

    const attributesInfo = [
        { id: "str", name: "文本4", desc: "文本388" },
        { id: "agi", name: "文本6", desc: "文本389" },
        { id: "con", name: "文本8", desc: "文本390" },
        { id: "wis", name: "文本10", desc: "文本391" },
        { id: "emp", name: "文本12", desc: "文本392" },
        { id: "wil", name: "文本14", desc: "文本393" },
        { id: "ldr", name: "文本16", desc: "文本394" },
        { id: "luck", name: "文本18", desc: "文本395" }
    ];

    const scenarios = [
        { type: 'human', text: "名字27文本396" },
        { type: 'human', text: "名字27文本397" },
        { type: 'human', text: "名字27文本398<request：名字27文本426>" },
        { type: 'vampire', text: "名字27文本399" },
        { type: 'werewolf', text: "名字27文本400名字27文本401" },
        { type: 'any', id: 'custom', text: "" }
    ];


    let currentStep = 1;
    let selectedRace = '';
    const TOTAL_POINTS = 400;
    const MIN_ATTR = 10;
    let attrValues = {};


    document.addEventListener('DOMContentLoaded', () => {
        attributesInfo.forEach(a => attrValues[a.id] = MIN_ATTR);
        renderAttrGrid();
        updatePathInfo('vampire');
        updatePathInfo('werewolf');
    });


    function selectRace(race, el) {
        selectedRace = race;
        document.querySelectorAll('.race-card').forEach(c => c.classList.remove('selected'));
        el.classList.add('selected');
        const desc = document.getElementById('race-desc');
        desc.style.display = 'block';
        if(race === 'human') desc.innerText = "文本402";
        else if(race === 'vampire') desc.innerText = "文本403";
        else desc.innerText = "文本404";
    }


    function updatePathInfo(type) {
        const path = document.getElementById(type + '-path').value;
        const rankSel = document.getElementById(type + '-rank');
        const data = type === 'vampire' ? vampireData : werewolfData;
        const info = data[path];


        let html = `<div>${info.desc}</div>`;
        if(info.needSire || info.needPartner) html += `<div style="margin-top:2px;color:#a55;">文本405</div>`;
        document.getElementById(type + '-path-desc').innerHTML = html;


        resetRankSelect(rankSel);
        if (type === 'vampire') {
            if (info.isThrall) setRankLocked(rankSel, "文本337");
            if (info.isHalfBlood) setRankLocked(rankSel, "文本321");
        }
        if (type === 'werewolf') {
            if (info.isCursed) setRankLocked(rankSel, "文本357");
            if (info.isHalfBlood) setRankLocked(rankSel, "文本347");
        }
    }

    function setRankLocked(sel, val) {
        for(let opt of sel.options) if(opt.value === val) opt.disabled = false;
        sel.value = val;
        sel.disabled = true;
    }
    function resetRankSelect(sel) {
        sel.disabled = false;
        for(let opt of sel.options) {

            if(["文本337", "文本357", "文本321", "文本347"].includes(opt.value)) opt.disabled = true;
        }
        if(sel.options[sel.selectedIndex].disabled) sel.selectedIndex = 0;
    }


    function renderAttrGrid() {
        const grid = document.getElementById('attr-grid');
        grid.innerHTML = '';
        attributesInfo.forEach(attr => {
            const div = document.createElement('div');
            div.className = 'attr-item';
            div.innerHTML = `
                <div class="attr-header">
                    <span>${attr.name}</span>
                </div>
                <div class="attr-input-group">
                    <div class="attr-btn" onclick="changeAttr('${attr.id}', -10)">-</div>
                    <input type="number" class="attr-input" id="attr-${attr.id}" value="${attrValues[attr.id]}"
                           onchange="manualAttr('${attr.id}')">
                    <div class="attr-btn" onclick="changeAttr('${attr.id}', 10)">+</div>
                </div>
                <div class="attr-desc">${attr.desc}</div>
            `;
            grid.appendChild(div);
        });
        updatePointsDisplay();
    }

    function getUsedPoints() {
        return Object.values(attrValues).reduce((a, b) => a + b, 0);
    }

    function updatePointsDisplay() {
        const used = getUsedPoints();
        const remain = TOTAL_POINTS - used;
        const disp = document.getElementById('points-display');
        disp.innerText = `文本361: ${remain}`;
        disp.className = remain === 0 ? 'points-remain' : (remain > 0 ? 'points-remain' : '文本406');
        const nextBtn = document.getElementById('next-btn');
        if(currentStep === 3) nextBtn.disabled = (remain !== 0);
    }

    function changeAttr(id, delta) {
        const current = attrValues[id];
        const newVal = current + delta;
        const remain = TOTAL_POINTS - getUsedPoints();
        if (newVal < MIN_ATTR) return;
        if (delta > 0 && remain < delta) return;
        attrValues[id] = newVal;
        document.getElementById('attr-' + id).value = newVal;
        updatePointsDisplay();
    }

    function manualAttr(id) {
        const el = document.getElementById('attr-' + id);
        let val = parseInt(el.value);
        if(isNaN(val)) val = MIN_ATTR;
        if(val < MIN_ATTR) val = MIN_ATTR;
        let otherUsed = 0;
        for(let key in attrValues) if(key !== id) otherUsed += attrValues[key];
        if (val + otherUsed > TOTAL_POINTS) val = TOTAL_POINTS - otherUsed;
        attrValues[id] = val;
        el.value = val;
        updatePointsDisplay();
    }


    function renderScenarios() {
        const list = document.getElementById('scenario-list');
        list.innerHTML = '';
        scenarios.forEach((sc) => {
            if(sc.type !== 'any' && sc.type !== selectedRace) return;
            const div = document.createElement('div');
            div.className = 'scenario-item';
            if(sc.id === 'custom') {
                div.innerHTML = `
                    <span class="scenario-tag">文本407</span>
                    <textarea id="custom-start-text" style="width:100%;height:40px;margin-top:5px;background:transparent;border:none;resize:none;color:#ccc;font-family:inherit;" placeholder="">>> 文本408..."></textarea>
                    <div style="text-align:right;margin-top:2px;">
                        <button class="btn btn-primary" style="padding:4px 12px;font-size:10px;" onclick="startGameCustom(event)">文本409</button>
                    </div>
                `;
                div.onclick = (e) => e.stopPropagation();
            } else {
                div.innerHTML = `
                    <span class="scenario-tag">${sc.type === 'human' ? '文本293' : (sc.type === 'vampire' ? '文本294' : '文本295')}</span>
                    <div class="scenario-text">${sc.text.replace(/</g, '&lt;')}</div>
                `;
                div.onclick = () => startGame(sc.text);
            }
            list.appendChild(div);
        });
    }


    function nextStep() {
        if(currentStep === 1) {
            if(!selectedRace) { alert("文本410"); return; }
            toggleView(1, 2);
            document.getElementById('form-human').style.display = selectedRace === 'human' ? 'block' : 'none';
            document.getElementById('form-vampire').style.display = selectedRace === 'vampire' ? 'block' : 'none';
            document.getElementById('form-werewolf').style.display = selectedRace === 'werewolf' ? 'block' : 'none';
            document.getElementById('next-btn').innerText = "文本411";
        } else if(currentStep === 2) {
            saveProfileToWI();
            toggleView(2, 3);
            updatePointsDisplay();
            document.getElementById('next-btn').innerText = "文本412";
        } else if(currentStep === 3) {
            toggleView(3, 4);
            renderScenarios();
            document.getElementById('next-btn').style.display = 'none';
        }
        currentStep++;
        updateBtnState();
    }

    function prevStep() {
        if(currentStep === 2) toggleView(2, 1);
        else if(currentStep === 3) toggleView(3, 2);
        else if(currentStep === 4) toggleView(4, 3);
        currentStep--;
        updateBtnState();
    }

    function toggleView(from, to) {
        document.getElementById(from === 2 ? 'step-2-wrapper' : 'step-'+from).classList.remove('active');
        document.getElementById(to === 2 ? 'step-2-wrapper' : 'step-'+to).classList.add('active');
    }

    function updateBtnState() {
        const prev = document.getElementById('prev-btn');
        const next = document.getElementById('next-btn');
        if(currentStep === 1) {
            prev.style.display = 'none'; next.innerText = "文本368";
        } else {
            prev.style.display = 'inline-block';
        }
        if(currentStep === 4) next.style.display = 'none';
        else next.style.display = 'inline-block';
    }


    function saveProfileToWI() {
        let content = `[文本413]\n文本414: ${selectedRace === 'human' ? '文本293' : (selectedRace === 'vampire' ? '文本294' : '文本295')}\n`;
        let instruction = "";

        if (selectedRace === 'human') {
            const bg = document.getElementById('human-bg').value;
            const skill = document.getElementById('human-skill').value;
            const att = document.getElementById('human-attitude').value;
            content += `文本415: ${bg}\n文本300: ${skill}\n文本416: ${att}`;
        } else {
            const type = selectedRace;
            const path = document.getElementById(type + '-path').value;
            const rank = document.getElementById(type + '-rank').value;
            const data = type === 'vampire' ? vampireData : werewolfData;
            const info = data[path];

            content += `文本417: ${rank}\n文本418: ${path}\n`;
            if(info.bond) content += `文本419: ${info.bond}\n`;

            if(info.needSire) {
                const title = type === 'vampire' ? '文本332' : 'Alpha';
                instruction = `\n[文本420]\nAI文本421NPC文本422${title}文本423${info.bond}。`;
            } else if(info.needPartner) {
                instruction = `\n[文本420]\nAI文本421NPC文本424${info.bond}。`;
            }
        }
        const fullContent = content + instruction;
        const cmd = `/setentryfield file="🥀名字66" uid=9 field=content ${JSON.stringify(fullContent)}`;
        if(window.triggerSlash) window.triggerSlash(cmd);
        else console.log("文本425", cmd);
    }

    function startGame(text) { sendFinalCommand(text); }
    function startGameCustom(e) { e.stopPropagation(); const t = document.getElementById('custom-start-text').value; if(t) sendFinalCommand(t); }

    function sendFinalCommand(startText) {
        const attrStr = Object.keys(attrValues).map(k => {
             const name = attributesInfo.find(a=>a.id===k).name;
             return `${name}:${attrValues[k]}`;
        }).join(', ');
        const finalMsg = startText + `\n\n[System Info: Initial Attributes Allocated]\n[Stats: ${attrStr}]`;
        const cmd = `/send ${finalMsg} | /trigger`;
        if(window.triggerSlash) window.triggerSlash(cmd);
        else alert(cmd);
    }
</script>

</body>
</html>
